mapper.sql:
af.delete_yn = 'N' and ( exists ( select 1 from brd_qna bq where af.link_sys_id in (bq.sys_id, bq.file_ulid) and bq.delete_yn = 'N'
and bq.sys_plant_cd = #{read.sysPlantCd}
) or exists ( select 1 from brd_notice bn where bn.file_ulid = af.link_sys_id and bn.delete_yn = 'N' and ( bn.sys_plant_cd = #{read.sysPlantCd}
or ( bn.use_yn = 'Y' and bn.target in ('all', #{read.noticeTarget}) and bn.start_date <= now() )
) ) or exists ( select 1 from store_menu_detail smd where smd.file_ulid = af.link_sys_id and smd.delete_yn = 'N' and smd.sys_plant_cd = #{read.sysPlantCd} ) or exists ( select 1 from store_menu_option_detail smod where smod.file_ulid = af.link_sys_id and smod.delete_yn = 'N' and smod.sys_plant_cd = #{read.sysPlantCd} ) )

mapper.update:
update attach_file af set ord_no = changes.ord_no, modify_user_id = #{userId}, modify_datetime = now() from (values
(cast(#{item.sysId} as varchar), cast(#{item.ordNo} as integer))
) as changes(sys_id, ord_no) where af.sys_id = changes.sys_id and

update attach_file af set delete_yn = 'Y', modify_user_id = #{userId}, modify_datetime = now() where af.sys_id in
#{id}
and

mapper.select:
select sys_id , link_sys_id , original_file_nm , convert_file_nm , file_ext , mime_type , file_size , file_path , pdf_yn , ord_no from attach_file af where af.sys_id in
#{id}
and order by af.sys_id for update
